      "fact": "Horizontal axis label 'Year'."
    },
    {
      "location": "Main plot area, x≈100-950, y≈140-880",
      "fact": "A single solid blue line chart connecting data points for each year from 2018 to 2023."
    },
    {
      "location": "Plot area, y≈210-280",
      "fact": "The blue line fluctuates in the upper portion of the graph, starting high, dipping, rising to a peak, and then leveling off."
    },
    {
      "location": "Plot area, x≈450, y≈210",
      "fact": "The line reaches its highest visual point (peak) at the 2020 mark."
    },
    {
      "location": "Plot area, x≈275, y≈290",
      "fact": "The line reaches its lowest visual point (trough) at the 2019 mark."
    },
    {
      "location": "Plot area, x≈600-950, y≈260-270",
      "fact": "From 2021 to 2023, the line becomes nearly horizontal, indicating a plateau with very slight downward slope."
    }
  ],
  "printed_facts": [
    {
      "location": "Y-axis, x≈80-100",
      "fact": "Tick labels from bottom to top: 0, 400, 800, 1,200, 1,600, 2,000, 2,400, 2,800."
    },
    {
      "location": "X-axis, y≈880-900",
      "fact": "Tick labels from left to right: 2018, 2019, 2020, 2021, 2022, 2023."
    },
    {
      "location": "Data point at 2018 (x≈100)",
      "fact": "The line starts at a Recovery Score of approximately 2,800."
    },
    {
      "location": "Data point at 2019 (x≈275)",
      "fact": "The line drops to a Recovery Score of approximately 2,400."
    },
    {
      "location": "Data point at 2020 (x≈450)",
      "fact": "The line rises to a peak Recovery Score slightly above 2,800 (approx 2,850)."
    },
    {
      "location": "Data point at 2021 (x≈625)",
      "fact": "The line drops to a Recovery Score of approximately 2,600."
    },
    {
      "location": "Data point at 2022 (x≈800)",
      "fact": "The line remains at a Recovery Score of approximately 2,600."
    },
    {
      "location": "Data point at 2023 (x≈950)",
      "fact": "The line ends at a Recovery Score slightly below 2,600 (approx 2,550)."
    }
  ],
